    55|/**
    56| * Decide whether a primary-route failure is safe to hand to the durable queue.
    57| * Only transient failures qualify — auth/validation failures are never retried.
    58| */
    59|export function shouldAttemptDurableFallback(
    60|  diagnostics: { statusCode?: number | null; stage?: string | null } | null,
    61|  failureMessage: string,
    62|): boolean {
    63|  const status = diagnostics?.statusCode ?? null;
    64|  if (status !== null) {
